pragma solidity ^0.8.20;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title TicTacToe
 * @notice Production-ready on-chain Tic Tac Toe with gas-optimized storage and griefing protection.
 * @dev Uses bit-packed storage for board state (2 bits per cell) to minimize SSTORE operations.
 */
contract TicTacToe is ReentrancyGuard {
    // ═══════════════════════════════════════════════════════════════
    // CONSTANTS & TYPES
    // ═══════════════════════════════════════════════════════════════

    /// @dev Time allowed per move before opponent can claim abandonment victory
    uint256 public constant MOVE_TIMEOUT = 1 hours;

    enum GameState { WAITING, ACTIVE, COMPLETED }

    struct Game {
        // --- Slot 0: Hot State (Updated every move) ---
        address turn;       // 20 bytes: Current player to move
        uint32 lastMove;    // 4 bytes: Timestamp of last action
        uint32 board;       // 4 bytes: Packed grid (2 bits/cell, 0=Empty, 1=P1, 2=P2)
        uint8 moves;        // 1 byte: Move counter (max 9)
        GameState state;    // 1 byte: Current lifecycle state
        // Total: 30 bytes (Fits in 1 slot, single SSTORE update)

        // --- Slot 1: Immutable Player 1 ---
        address player1;    // 20 bytes

        // --- Slot 2: Immutable Player 2 ---
        address player2;    // 20 bytes

        // --- Slot 3: Winner ---
        address winner;     // 20 bytes
    }

    // ═══════════════════════════════════════════════════════════════
    // STATE VARIABLES
    // ═══════════════════════════════════════════════════════════════

    /// @notice Lookup for all game sessions
    mapping(uint256 => Game) public games;

    /// @notice Counter for generating unique game IDs
    uint256 public nextGameId;

    // ═══════════════════════════════════════════════════════════════
    // EVENTS
    // ═══════════════════════════════════════════════════════════════

    event GameCreated(uint256 indexed gameId, address indexed creator);
    event GameJoined(uint256 indexed gameId, address indexed joiner);
    event MoveMade(uint256 indexed gameId, address indexed player, uint8 cellIndex);
    event GameFinished(uint256 indexed gameId, address indexed winner, bool isDraw);

    // ═══════════════════════════════════════════════════════════════
    // CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════

    constructor() {
        // Intentionally empty
    }

    // ═══════════════════════════════════════════════════════════════
    // GAMEPLAY FUNCTIONS
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice Initialize a new game session.
     * @return gameId The ID of the created game.
     */
    function createGame() external returns (uint256 gameId) {
        gameId = nextGameId++;
        Game storage g = games[gameId];

        g.player1 = msg.sender;
        g.lastMove = uint32(block.timestamp);
        g.state = GameState.WAITING;

        // Slots 2 & 3 (player2, winner) and board are 0-initialized by default

        emit GameCreated(gameId, msg.sender);
    }

    /**
     * @notice Join an existing game in WAITING state.
     * @param gameId The ID of the game to join.
     */
    function joinGame(uint256 gameId) external {
        Game storage g = games[gameId];

        require(g.state == GameState.WAITING, "Game not waiting");
        require(g.player1 != address(0), "Game does not exist");
        require(msg.sender != g.player1, "Cannot play against self");

        g.player2 = msg.sender;
        g.turn = g.player1; // Player 1 (Creator) always starts
        g.state = GameState.ACTIVE;
        g.lastMove = uint32(block.timestamp);

        emit GameJoined(gameId, msg.sender);
    }

    /**
     * @notice Submit a move to mark a cell.
     * @param gameId The ID of the active game.
     * @param cellIndex The grid index (0-8) to mark.
     * 
     * Grid Layout:
     * 0 1 2
     * 3 4 5
     * 6 7 8
     */
    function makeMove(uint256 gameId, uint8 cellIndex) external nonReentrant {
        require(cellIndex < 9, "Invalid cell index");

        Game storage g = games[gameId];
        require(g.state == GameState.ACTIVE, "Game not active");
        require(msg.sender == g.turn, "Not your turn");

        // --- Load Board State ---
        uint32 currentBoard = g.board;
        uint32 shift = uint32(cellIndex) * 2;

        // Check if cell is empty (bits are 00)
        require(((currentBoard >> shift) & 3) == 0, "Cell already occupied");

        // Determine mark: Player1 = 1 (01), Player2 = 2 (10)
        // We trust msg.sender == turn, and turn matches p1 or p2 logic
        uint32 mark = (msg.sender == g.player1) ? 1 : 2;

        // --- Update State ---
        // Apply move
        currentBoard |= (mark << shift);
        g.board = currentBoard;
        g.moves++;
        g.lastMove = uint32(block.timestamp);

        emit MoveMade(gameId, msg.sender, cellIndex);

        // --- Check Outcomes ---
        if (_checkWin(currentBoard, mark)) {
            _endGame(g, gameId, msg.sender, false);
        } else if (g.moves >= 9) {
            _endGame(g, gameId, address(0), true);
        } else {
            // Pass turn
            g.turn = (msg.sender == g.player1) ? g.player2 : g.player1;
        }
    }

    /**
     * @notice Claim victory if the active player has timed out.
     * @dev Prevents griefing where a losing player stops playing.
     * @param gameId The ID of the game.
     */
    function claimTimeout(uint256 gameId) external nonReentrant {
        Game storage g = games[gameId];

        require(g.state == GameState.ACTIVE, "Game not active");
        require(block.timestamp > uint256(g.lastMove) + MOVE_TIMEOUT, "Timeout not reached");
        require(msg.sender == g.player1 || msg.sender == g.player2, "Not a player");
        require(msg.sender != g.turn, "Cannot claim timeout on self");

        // The caller wins because the opponent (g.turn) timed out
        _endGame(g, gameId, msg.sender, false);
    }

    // ═══════════════════════════════════════════════════════════════
    // INTERNAL LOGIC
    // ═══════════════════════════════════════════════════════════════

    function _endGame(Game storage g, uint256 gameId, address winner, bool isDraw) internal {
        g.state = GameState.COMPLETED;
        g.winner = winner;
        g.turn = address(0); // Clear turn pointer
        emit GameFinished(gameId, winner, isDraw);
    }

    /**
     * @dev Checks if the given player mark has won.
     * @param board The packed board state.
     * @param mark The player identifier (1 or 2).
     */
    function _checkWin(uint32 board, uint32 mark) internal pure returns (bool) {
        // Rows
        if (_isRowMatch(board, mark, 0, 1, 2)) return true;
        if (_isRowMatch(board, mark, 3, 4, 5)) return true;
        if (_isRowMatch(board, mark, 6, 7, 8)) return true;

        // Columns
        if (_isRowMatch(board, mark, 0, 3, 6)) return true;
        if (_isRowMatch(board, mark, 1, 4, 7)) return true;
        if (_isRowMatch(board, mark, 2, 5, 8)) return true;

        // Diagonals
        if (_isRowMatch(board, mark, 0, 4, 8)) return true;
        if (_isRowMatch(board, mark, 2, 4, 6)) return true;

        return false;
    }

    function _isRowMatch(uint32 board, uint32 mark, uint8 a, uint8 b, uint8 c) private pure returns (bool) {
        // Check 2 bits at index a, b, c
        return ((board >> (a * 2)) & 3) == mark &&
               ((board >> (b * 2)) & 3) == mark &&
               ((board >> (c * 2)) & 3) == mark;
    }

    // ═══════════════════════════════════════════════════════════════
    // VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice Unpack the board state into an array.
     * @param gameId The game ID.
     * @return boardArr A 9-element array where 0=Empty, 1=Player1, 2=Player2.
     */
    function getBoard(uint256 gameId) external view returns (uint8[9] memory boardArr) {
        uint32 packed = games[gameId].board;
        for (uint8 i = 0; i < 9; i++) {
            boardArr[i] = uint8((packed >> (i * 2)) & 3);
        }
    }
}

